JS_COMMENT_OLD = r'''  // An office search under Staffer leaves out the current staff who lack the coverage the model requires (no payroll record and not an operational staffer; a person with dated directory work can be one) and searches to the rest (D-086); the answer counts them in uncovered_staff_count. One plain line with the result, only when there are some.
'''
JS_COMMENT_NEW = r'''  // An office search under Staffer leaves out the current staff who lack the coverage the model requires (no payroll record and not an operational staffer; a person with dated directory work can be one) and searches to the rest (D-086); the answer counts them in uncovered_staff_count and says in uncovered_basis which coverage they lack: payroll_or_roster, or roster where the comparison reads directory episodes only (work_sources=directory has no payroll evidence to cover anyone), and the line names that coverage. Any other basis, or none (an older server), gets the payroll-or-roster wording. One plain line with the result, only when there are some.
'''
